def arrow(x1,y1,x2,y2,color=blue,dash=False):
 c.setStrokeColor(color);c.setFillColor(color);c.setLineWidth(1.4);c.setDash(4,3) if dash else c.setDash();c.line(x1,y1,x2,y2);c.setDash()
